/**
 * Login callback page chibi visuals (PR3, U-7 裁决落码).
 *
 * 来源:apps/desktop/src/renderer/assets/login/chibi/chibi-*@2x.png(2026-07-22
 * 换用用户提供的退底透明源,280×280 @1x 等比 Lanczos 放大到 560×560=280×280@2x,
 * asset-manifest.md 登记)→ cwebp -q 82 -exact 转码为 webp 后 base64 内嵌。
 * U-7 硬约束:单张 ≤120KB(实测 success 72.4KB / failure 76.3KB / neutral 70.7KB)。
 * 透明底:三张全透明像素占比约 37%(旧资产为 #FBFBFB 满底不透明,在 Dark 卡上显
 * 白色矩形——2026-07-22 手测缺陷,本次退底修复),cwebp -exact 保留透明区 RGB。
 *
 * 为什么是 data URI:回调页运行在系统浏览器的独立 HTML 里,拿不到 renderer bundle
 * 路径、Electron 私有协议与 cindy-media://(callback-pages-classification.md 页壳
 * 改造点 2);data URI 随 HTML 一次性下发,无额外静态资源伺服面。
 * 规则 25 边界:构建期内嵌的 UI 静态资源,不是运行时媒体字节,不走 cindy-media 总仓。
 */

/** 回调卡三类立绘(visualKind → 280×280@2x webp data URI)。 */
export const LOGIN_CALLBACK_CHIBI: Record<'success' | 'failure' | 'neutral', string> = {
  success:
    'data:image/webp;base64,',
  failure:
    'data:image/webp;base64,',
  neutral:
    'data:image/webp;base64,',
};
